// ============================================================
// Build SerpAPI search queries — rotate through D2C industries
// Pick 3 industries per run to avoid rate limits
// ============================================================
const allIndustries = [
  'skincare', 'fashion', 'fitness', 'supplements', 'food',
  'home decor', 'jewelry', 'baby care', 'wellness',
  'SaaS', 'fintech', 'edtech', 'healthtech', 'real estate',
  'gaming', 'insurtech'
];

// Rotate: use day-of-year to pick a starting offset
const dayOfYear = Math.floor((Date.now() - new Date(new Date().getFullYear(), 0, 0).getTime()) / 86400000);
const offset = (Math.floor(dayOfYear / 3) * 3) % allIndustries.length;
const industries = [];
for (let i = 0; i < 3; i++) {
  industries.push(allIndustries[(offset + i) % allIndustries.length]);
}

const serpQueries = [];
for (const ind of industries) {
  serpQueries.push(`"${ind} brand" India Facebook ads`);
  serpQueries.push(`"${ind} brand" India Instagram advertising`);
  serpQueries.push(`D2C ${ind} brand scaling Meta ads India`);
  serpQueries.push(`"${ind} startup" India performance marketing`);
  serpQueries.push(`site:facebook.com/ads/library "${ind}" brand India`);
}

return [{ json: { serpQueries, industries, source: 'schedule' } }];

// ============================================================
// Parse webhook body — accept industries or brand_names
// ============================================================
const body = $input.first().json.body || $input.first().json;

const allIndustries = [
  'skincare', 'fashion', 'fitness', 'supplements', 'food',
  'home decor', 'jewelry', 'baby care', 'wellness',
  'SaaS', 'fintech', 'edtech', 'healthtech', 'real estate',
  'gaming', 'insurtech'
];

let industries = [];
let serpQueries = [];

const brandNames = Array.isArray(body.brand_names) ? body.brand_names : [];
const reqIndustries = Array.isArray(body.industries) ? body.industries : [];

if (brandNames.length > 0) {
  // Direct brand search
  industries = ['custom'];
  for (const brand of brandNames) {
    serpQueries.push(`"${brand}" Facebook ads India`);
    serpQueries.push(`"${brand}" Instagram advertising India`);
    serpQueries.push(`"${brand}" Meta ad spend India D2C`);
    serpQueries.push(`site:facebook.com/ads/library "${brand}" India`);
  }
} else {
  // Use provided industries or default rotation
  industries = reqIndustries.length > 0 ? reqIndustries.slice(0, 4) : allIndustries.slice(0, 3);
  for (const ind of industries) {
    serpQueries.push(`"${ind} brand" India Facebook ads`);
    serpQueries.push(`"${ind} brand" India Instagram advertising`);
    serpQueries.push(`D2C ${ind} brand scaling Meta ads India`);
    serpQueries.push(`"${ind} startup" India performance marketing`);
    serpQueries.push(`site:facebook.com/ads/library "${ind}" brand India`);
  }
}

return [{ json: { serpQueries, industries, source: 'webhook', brandNames } }];

// ============================================================
// Search brands via SerpAPI — extract brand names + websites
// Uses this.helpers.httpRequest() for reliable HTTP calls
// ============================================================
const input = $input.first().json;
const queries = input.serpQueries || [];
const industries = input.industries || [];
const SERP_KEY = 'b183c082b67f0971673dbab7ce0a14883f75e5012d09720d17c540efce67bc39';

// Generic domains to skip
const SKIP_DOMAINS = new Set([
  'wikipedia.org', 'linkedin.com', 'amazon.in', 'amazon.com',
  'flipkart.com', 'youtube.com', 'instagram.com', 'facebook.com',
  'twitter.com', 'x.com', 'reddit.com', 'quora.com', 'pinterest.com',
  'medium.com', 'forbes.com', 'inc42.com', 'yourstory.com',
  'economictimes.com', 'livemint.com', 'businessinsider.com',
  'shopify.com', 'nykaa.com', 'myntra.com', 'ajio.com',
  'meesho.com', 'snapdeal.com', 'tatacliq.com', 'google.com',
  'play.google.com', 'apps.apple.com', 'trustpilot.com',
  'glassdoor.com', 'crunchbase.com', 'zoominfo.com',
  'dnb.com', 'bbb.org', 'yelp.com'
]);

function getDomain(link) {
  if (!link) return '';
  const m = link.match(/^https?:\/\/(?:www\.)?([^\/?#]+)/i);
  return m ? m[1].toLowerCase() : '';
}

function isSkipDomain(domain) {
  if (!domain) return true;
  for (const skip of SKIP_DOMAINS) {
    if (domain === skip || domain.endsWith('.' + skip)) return true;
  }
  return false;
}

function extractBrandName(title, snippet) {
  // Try to extract a clean brand name from the title
  let name = title || '';
  // Remove common suffixes
  name = name.replace(/\s*[-|:].*/g, '').trim();
  name = name.replace(/\s*(Official Site|Home|Shop|Buy|Online).*$/i, '').trim();
  if (name.length > 50) name = name.substring(0, 50);
  return name || 'Unknown';
}

const seen = new Map(); // domain -> brand info
const results = [];

// Process queries with delay
for (let i = 0; i < queries.length; i++) {
  const query = queries[i];
  try {
    const url = `https://serpapi.com/search.json?engine=google&q=${encodeURIComponent(query)}&api_key=${SERP_KEY}&gl=in&hl=en&num=10`;
    const resp = await this.helpers.httpRequest({ method: 'GET', url, json: true });

    const organicResults = resp.organic_results || [];
    for (const r of organicResults) {
      const domain = getDomain(r.link);
      if (!domain || isSkipDomain(domain)) continue;
      if (seen.has(domain)) continue;

      const brandName = extractBrandName(r.title, r.snippet);
      // Guess industry from the query
      let industry = 'D2C';
      for (const ind of industries) {
        if (ind !== 'custom' && query.toLowerCase().includes(ind.toLowerCase())) {
          industry = ind;
          break;
        }
      }

      const info = {
        brand_name: brandName,
        website: r.link,
        domain: domain,
        snippet: (r.snippet || '').substring(0, 300),
        industry: industry
      };
      seen.set(domain, info);
      results.push(info);
    }
  } catch (e) {
    // Skip failed queries silently
  }

  // 1.2s delay between requests
  if (i < queries.length - 1) {
    await new Promise(resolve => setTimeout(resolve, 1200));
  }
}

// Cap at 30
const capped = results.slice(0, 30);

return [{ json: {
  brands: capped,
  totalFound: capped.length,
  queriesRun: queries.length,
  industries: industries,
  source: input.source || 'schedule'
} }];

// ============================================================
// Deduplicate: remove brands already in Airtable Leads
// ============================================================
const searchData = $('als-search-brands').first().json;
const brands = searchData.brands || [];
const existingResponse = $input.first().json;
const existingRecords = existingResponse.records || [];

// Build sets of existing domains and company names (lowercased)
const existingDomains = new Set();
const existingNames = new Set();

for (const rec of existingRecords) {
  const f = rec.fields || {};
  if (f.company_name) existingNames.add(f.company_name.toLowerCase().trim());
  if (f.website) {
    const m = f.website.match(/^https?:\/\/(?:www\.)?([^\/?#]+)/i);
    if (m) existingDomains.add(m[1].toLowerCase());
  }
}

// Also skip article/news domains
const newsDomains = new Set([
  'inc42.com', 'yourstory.com', 'entrackr.com', 'moneycontrol.com',
  'businesstoday.in', 'ndtv.com', 'hindustantimes.com', 'theprint.in',
  'news18.com', 'firstpost.com', 'scroll.in', 'thehindubusinessline.com',
  'financialexpress.com', 'livemint.com', 'economic-times.com'
]);

const newBrands = [];
let duplicatesRemoved = 0;

for (const brand of brands) {
  const domain = (brand.domain || '').toLowerCase();
  const name = (brand.brand_name || '').toLowerCase().trim();

  // Skip if domain or name already exists
  if (existingDomains.has(domain)) { duplicatesRemoved++; continue; }
  if (existingNames.has(name) && name.length > 2) { duplicatesRemoved++; continue; }
  // Skip news domains
  if (newsDomains.has(domain)) { duplicatesRemoved++; continue; }

  newBrands.push(brand);
}

return [{ json: {
  newBrands,
  totalFound: searchData.totalFound,
  duplicatesRemoved,
  industries: searchData.industries,
  source: searchData.source
} }];

// ============================================================
// Build Gemini prompt to analyze brands for UGC opportunity
// ============================================================
const data = $input.first().json;
const brands = (data.newBrands || []).slice(0, 12);

if (brands.length === 0) {
  return [{ json: { _skip: true, reason: 'No brands to analyze' } }];
}

const brandList = brands.map((b, i) => {
  return `${i + 1}. Brand: ${b.brand_name}\n   Website: ${b.website}\n   Domain: ${b.domain}\n   Industry hint: ${b.industry}\n   Context: ${b.snippet}`;
}).join('\n\n');

const systemPrompt = `You are a competitive intelligence analyst for Cosmisk, a UGC (User-Generated Content) agency based in India. Your job is to analyze D2C brands that are actively advertising on Meta (Facebook/Instagram) and identify which ones are NOT using UGC-style content — those are the best sales prospects.

UGC-style content includes: creator testimonials, unboxing videos, day-in-life vlogs featuring products, before/after transformations by real people, talking-head reviews. Brands using studio-shot product photography, graphic design ads, or stock footage are NOT using UGC.

For each brand, provide your analysis as a JSON object. Base your assessment on the brand name, website, industry, and any context clues from search snippets.`;

const userPrompt = `Analyze these ${brands.length} Indian D2C brands that appear to be running Meta ads. For each, assess their content strategy and UGC usage.

${brandList}

Return a JSON array with exactly ${brands.length} objects. Each object must have these keys:
- company_name (string): cleaned-up brand name
- website (string): the brand's website URL
- industry (string): their industry (skincare, fashion, fitness, supplements, food, home decor, jewelry, baby care, wellness, or other)
- using_ugc (string): "yes", "partially", or "no" — your best assessment
- ad_spend_level (string): "low", "medium", or "high" — estimate based on context
- opportunity_score (number 1-10): higher = more opportunity for Cosmisk. Non-UGC + high ad spend = highest score
- contact_title (string): likely decision maker title (e.g., "Founder", "Marketing Head", "Brand Manager", "CMO")
- outreach_angle (string): 1-2 sentences on why they should switch to UGC
- pitch_hook (string): one line personalized pitch
- suggested_platform (string): best platform to reach them ("LinkedIn", "Instagram DM", "Email", "Cold Call")
- email (string): likely contact email for the brand. Infer from the domain (e.g., hello@domain.com, info@domain.com, contact@domain.com). If unknown, use empty string.

Return ONLY the JSON array, no markdown fences, no extra text.`;

const requestBody = {
  systemInstruction: { parts: [{ text: systemPrompt }] },
  contents: [{ role: 'user', parts: [{ text: userPrompt }] }],
  generationConfig: {
    temperature: 0.3,
    maxOutputTokens: 16384,
    thinkingConfig: { thinkingBudget: 0 }
  }
};

return [{ json: {
  requestBody,
  brandCount: brands.length,
  industries: data.industries,
  source: data.source
} }];

// ============================================================
// Parse Gemini response — filter high-opportunity non-UGC brands
// Build Airtable batch create + Slack message
// ============================================================
const geminiResp = $input.first().json;
const prevData = $('als-build-prompt').first().json;
const industries = prevData.industries || [];
const source = prevData.source || 'schedule';

let rawText = '';
try {
  rawText = geminiResp.candidates[0].content.parts[0].text || '';
} catch (e) {
  // Gemini may have failed
  return [{ json: {
    batchBody: { records: [] },
    slackMsg: ':warning: *Ad Library Scanner* — Gemini analysis failed. No brands processed this run.',
    count: 0,
    topBrands: [],
    industries,
    source
  } }];
}

// Clean markdown fences
let cleaned = rawText.trim();
if (cleaned.startsWith('```')) {
  cleaned = cleaned.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '');
}

// Parse JSON — with object-by-object salvage for truncated responses
let analyzed = [];
try {
  analyzed = JSON.parse(cleaned);
} catch (e) {
  // Try to salvage individual objects from truncated JSON array
  try {
    // Remove leading [ and try to find complete objects
    const inner = cleaned.replace(/^\s*\[/, '').replace(/\]\s*$/, '');
    const objRegex = /\{[^{}]*(?:\{[^{}]*\}[^{}]*)*\}/g;
    const matches = inner.match(objRegex) || [];
    for (const m of matches) {
      try {
        analyzed.push(JSON.parse(m));
      } catch (e2) { /* skip malformed */ }
    }
  } catch (e3) { /* give up */ }
}

if (!Array.isArray(analyzed)) analyzed = [analyzed];

// Filter: opportunity_score >= 6 AND using_ugc != 'yes'
const qualified = analyzed.filter(b => {
  const score = Number(b.opportunity_score) || 0;
  const ugc = (b.using_ugc || '').toLowerCase();
  return score >= 6 && ugc !== 'yes';
});

// Sort by opportunity score descending
qualified.sort((a, b) => (Number(b.opportunity_score) || 0) - (Number(a.opportunity_score) || 0));

// Build Airtable batch create body (max 10 per request)
const records = qualified.slice(0, 10).map(b => {
  const notes = [
    'Source: Ad Library Scanner (auto-discovered)',
    `Discovery: Running Meta ads without UGC`,
    `Industry: ${b.industry || 'D2C'}`,
    `Ad Spend: ${b.ad_spend_level || 'unknown'}`,
    `UGC Usage: ${b.using_ugc || 'unknown'}`,
    `Opportunity Score: ${b.opportunity_score || '?'}/10`,
    `Outreach Angle: ${b.outreach_angle || 'N/A'}`,
    `Pitch: ${b.pitch_hook || 'N/A'}`,
    `Suggested Platform: ${b.suggested_platform || 'N/A'}`,
    `Scan Date: ${new Date().toISOString().split('T')[0]}`
  ].join('\n');

  const fields = {
      company_name: b.company_name || 'Unknown',
      contact_name: b.contact_title || 'Founder',
      stage: 'New',
      website: b.website || '',
      industry: b.industry || 'D2C',
      source: 'ad_library_scanner',
      notes: notes
    };
  // Add email if Gemini extracted one
  if (b.email && typeof b.email === 'string' && b.email.includes('@')) {
    fields.email = b.email.trim();
  }
  return { fields };
});

// Build Slack message
let slackMsg = '';
if (qualified.length === 0) {
  slackMsg = ':bar_chart: *Ad Library Scanner* — Scanned ' + (analyzed.length || 0) + ' brands, none qualified (score >= 6 + not using UGC). Industries: ' + industries.join(', ');
} else {
  const lines = [`:bar_chart: *Ad Library Scanner \u2014 ${qualified.length} Brands Found Running Ads Without UGC*`];
  lines.push('');
  lines.push('*Non-UGC brands (highest opportunity):*');
  qualified.forEach((b, i) => {
    const emoji = (Number(b.opportunity_score) || 0) >= 8 ? ':fire:' : ':small_orange_diamond:';
    lines.push(`${i + 1}. ${emoji} *${b.company_name}* (${b.industry || 'D2C'}) \u2014 Opportunity: ${b.opportunity_score}/10 | Ad Spend: ${b.ad_spend_level} | UGC: ${b.using_ugc}`);
    if (b.website) lines.push(`   ${b.website}`);
    if (b.pitch_hook) lines.push(`   _Pitch: ${b.pitch_hook}_`);
  });
  lines.push('');
  lines.push('_These brands are actively spending on Meta ads but NOT using creator content. Perfect prospects._');
  slackMsg = lines.join('\n');
}

return [{ json: {
  batchBody: { records },
  slackMsg,
  count: qualified.length,
  topBrands: qualified.slice(0, 5).map(b => b.company_name),
  industries,
  source
} }];
